/// <summary>
/// Extension class for updating the Rebate Transaction selection query for Provision/Post processes
/// </summary>
[ExtensionOf(classStr(TAMRebateFindTransRebateTable))]
internal final class METTAMRebateFindTransRebateTable_Extension
{
    private boolean shouldBeAggregated;
}

Method.Source:
    private Query setJournalAndLineFilters(Query _query)
    {
        Query qr = _query;
        
        if (rebateQueryBuilder.getJournalRecId() == -1)
        {
            if (qr.dataSourceTable(rebateQueryBuilder.journalTable()) && qr.dataSourceTable(rebateQueryBuilder.journalTable()).findRange(fieldNum(Common, RecId)))
            {
                qr.dataSourceTable(rebateQueryBuilder.journalTable()).findRange(fieldNum(Common, RecId)).value(SysQuery::value(rebateQueryBuilder.getJournalRecId()));
            }
        }

        if (rebateQueryBuilder.getLineRecId() == -1)
        {
            if (qr.dataSourceTable(rebateQueryBuilder.transTable()) && qr.dataSourceTable(rebateQueryBuilder.transTable()).findRange(fieldNum(Common, RecId)))
            {
                qr.dataSourceTable(rebateQueryBuilder.transTable()).findRange(fieldNum(Common, RecId)).value(SysQuery::value(rebateQueryBuilder.getLineRecId()));
            }
        }
        return qr;
    }

    /// <summary>
    /// This method build the query for generating the Rebate Transaction based on the filter criteria.
    /// Below customization changes the query used for Vendor Rebates
    /// Instead of picking the items from Item Group which is standard functioanlity, we need to pick the items from the Attribute group
    /// This custom change is defined on the Item Group in Rebate Manamgent module
    /// This change will happen for both Provision and post processes of the Vendor Rebates
    /// </summary>
    /// <returns>Modified Query Object </returns>
    protected Query buildJournalQuery()
    {
        Query metUpdatedQuery = next buildJournalQuery();        

        if( rebateTable.ModuleInventCustVend    == ModuleInventCustVend::Vend && //Vendor Rebates Only
            rebateTable.ItemCode                == TableGroupAll::GroupId && // Only when Item Group is selected (not All or Table
            rebateTable.ItemRelation) // if Item Relation/Group name is specified
        {
            if (false) //Modify query only if settings on Item Group are ideal (UseItemAttribute is yes and attribute group is selected)
            {
                QueryBuildDataSource qbdsTAMRebateGroupLink = metUpdatedQuery.dataSourceTable(tableNum(TAMRebateGroupLink));

                if(qbdsTAMRebateGroupLink)
                {
                    //Remove the Item Groups Item Ranges and dataasource if defined
                    qbdsTAMRebateGroupLink.clearRanges();
                    qbdsTAMRebateGroupLink.clearLinks();
                    qbdsTAMRebateGroupLink.enabled(false);
                }

                QueryBuildDataSource qbdsInventTable        = metUpdatedQuery.dataSourceTable(tableNum(InventTable));

                //<Start>Get the Products selection query based on the product attribute group defined on the Item Group
                GUPPricingAttributeGroup  GUPPricingAttributeGroup;
                GUPPricingObjectQueryBuilder queryBuilder = GUPPricingObjectQueryBuilder::constructFromPricingGroup(GUPPricingAttributeGroup);
                
                ///This "quieryBuilder.Build() can return a complex query (depending on the attributes selected in the attribute group) and not always possible to merge with other ranges, queries and table, hence all the ranges are added after doing a queryrun
                Query productAttributeQuery = queryBuilder.build();

                QueryRun queryRunProductAttributeQuery = new QueryRun(productAttributeQuery);
                while(queryRunProductAttributeQuery.next())
                {
                    //Add ranges in the original query for selecting the items based on the PRoduct attribute Group
                    InventTable itemsFromProductAttribute = queryRunProductAttributeQuery.get(tableNum(InventTable));
                    if(! this.metIsProductExcluded(itemsFromProductAttribute.RecId,GUPPricingAttributeGroup.Recid))
                    {
                        qbdsInventTable.addRange(FieldNum(InventTable,RecId)).value(queryValue(itemsFromProductAttribute.RecId));
                    }
                }
                
                //Additional range to cater for scenario when no items are present in ProductAttributeQuery, select no items
                qbdsInventTable.addRange(FieldNum(InventTable,RecId)).value(queryValue(0));

                //<End>Get the Products selection query based on the product attribute group defined on the Item Group
            }
        }        

        metUpdatedQuery = this.setJournalAndLineFilters(metUpdatedQuery);

        return metUpdatedQuery;
    }

    private boolean metIsProductExcluded(RecId _itemRecId,RecId _GUPPricingAttributeGroupRecId)
    {
        GUPPricingAttributeLineState GUPPricingAttributeLineState;

        //MS saves only excluded product details
        select firstonly RecId from GUPPricingAttributeLineState
            where GUPPricingAttributeLineState.LineTableId == tableNum(InventTable)
               && GUPPricingAttributeLineState.LineRecId   == _itemRecId
               && GUPPricingAttributeLineState.ParentTableId == tableNum(GUPPricingAttributeGroup)
               && GUPPricingAttributeLineState.ParentRecId   == _GUPPricingAttributeGroupRecId
               && GUPPricingAttributeLineState.LineType      == GUPPricingAttributeLineType::Exclude;

        if(GUPPricingAttributeLineState.RecId)
        {
            return true;
        }
        else
        {
            return false;
        }
    }

    /// <summary>
    /// CB705_VendorRebatePosting
    /// Consolidate by vendor rebate type
    /// </summary>
    /// <returns>Updated query</returns>
    protected Query getUnpostedRebateTransForPeriodQuery()
    {
        Query query = next getUnpostedRebateTransForPeriodQuery();
        
        // only consolidate for rebate, not provision
        if (TAMRebateParameters::find().METProcessVendRebateBasedVendRebType
        &&  rebateTransactionType == TAMRebateTransactionType::Rebate
        &&  !processByDeal // The deal is now configured to reconcile by line
        &&  rebateDeal.METInvoiceConsolidationByRebateType)
        {
            QueryBuildDataSource qbdsRebateDateTrans = query.dataSourceTable(tableNum(TAMRebateDateTrans));
            qbdsRebateDateTrans.addRange(fieldNum(TAMRebateDateTrans, METVendRebateTypeId)).value(queryValue(rebateTable.METVendRebateTypeId));

            // For process > rebate management and reconcile by line it adds a range on RebateId, so need to remove it
            qbdsRebateDateTrans.clearRange(fieldNum(TAMRebateDateTrans, RebateId));
            // Then we add similar range that is done with reconcile by deal so that we can consolidate the date transactions by vendor rebate type
            qbdsRebateDateTrans.addRange(fieldNum(TAMRebateDateTrans, RebateDeal)).value(queryValue(rebateDeal.RecId));
        }

        return query;
    }

    /// <summary>
    /// Pass the rebateTransactionType to rebateQueryBuilder
    /// </summary>
    protected void initialize()
    {
        next initialize();
        // Need to add logic to assign aggregation flag to rebate deal
        shouldBeAggregated = rebateDeal.METAggregatedBy != '';

        rebateQueryBuilder.metParmRebateTransactionType(rebateTransactionType);
    }

/// <summary>
/// CB201 - Add rebate transaction for the date period based on aggregator value
/// </summary>
/// <param name = "_rebateDatePeriod">Rebate calculation period</param>
/// <param name = "_rebateDateTrans">Rebate date transaction</param>
/// <param name = "_rebateTrans">Rebate transaction</param>
protected void addRebateTransIdForDatePeriod(TAMRebateDatePeriod _rebateDatePeriod, TAMRebateDateTrans _rebateDateTrans, TAMRebateTrans _rebateTrans)
{
    if (shouldBeAggregated)
    {
        // The rebate transaction is aggregated, so we need to add the aggregation string when identifying the rebate transaction ID. For those transactions that are aggregated together, they will share the same rebate transaction ID.
        _rebateDatePeriod.addRebateTransId(_rebateDateTrans.RebateFromDate, _rebateDateTrans.RebateToDate, _rebateTrans.RebateRefId, _rebateDateTrans.RebateTransId, _rebateDateTrans.METAggregatedStr);
    }
    else
    {
        next addRebateTransIdForDatePeriod(_rebateDatePeriod, _rebateDateTrans, _rebateTrans);
    }
}
